const BETA_CMD_MAX = 500;

function beta_cmd_fail(string $msg): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code(400);
    header('Content-Type: application/json');
    echo json_encode(['success' => false, 'message' => $msg]);
    exit();
}
function beta_cmd_msg($s): string { return trim(html_entity_decode(strip_tags(str_replace(['<br>', '<br/>'], ' ', (string) $s)))); }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $bPerm = ['Everyone', 'VIPs', 'All Subscribers', 'Tier 1 Subscriber', 'Tier 2 Subscriber', 'Tier 3 Subscriber', 'Mods', 'Broadcaster'];
    foreach (['permission', 'permission_response', 'usage_level'] as $k) {
        if (isset($_POST[$k]) && !in_array($_POST[$k], $bPerm, true)) beta_cmd_fail('Unknown permission level.');
    }
    if (isset($_POST['status']) && !in_array($_POST['status'], ['Enabled', 'Disabled'], true)) beta_cmd_fail('Status must be Enabled or Disabled.');
    foreach (['cooldown', 'cooldown_response'] as $k) {
        if (isset($_POST[$k]) && (!is_numeric($_POST[$k]) || (int) $_POST[$k] < 0 || (int) $_POST[$k] > 86400)) beta_cmd_fail('Cooldown must be a number of seconds.');
    }
    foreach (['response', 'command_response'] as $k) {
        if (isset($_POST[$k]) && mb_strlen((string) $_POST[$k]) > BETA_CMD_MAX) beta_cmd_fail('Response is longer than ' . BETA_CMD_MAX . ' characters.');
    }
}

function beta_cmd_die($msg): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code(502);
    header('Content-Type: application/json');
    echo json_encode(['success' => false, 'message' => beta_cmd_msg($msg)]);
    exit();
}
if ($_SERVER['REQUEST_METHOD'] === 'POST' && !isset($_POST['action'])) {
    // Permission and status saves end in a Location redirect on the live page.
    ob_start();
    register_shutdown_function(function () {
        $redirect = false;
        foreach (headers_list() as $h) { if (stripos($h, 'Location:') === 0) { $redirect = true; } }
        while (ob_get_level() > 0) { ob_end_clean(); }
        header_remove('Location');
        http_response_code($redirect ? 200 : 400);
        header('Content-Type: application/json');
        echo json_encode(['success' => $redirect, 'message' => $redirect ? 'Saved.' : 'Nothing changed.']);
    });
}


// Page Title
$pageTitle = t('builtin_commands_page_title');

// Include files for database and user data
require_once "/var/www/config/db_connect.php";
include '/var/www/config/twitch.php';
